params.command:
$candidates=@(
  (Join-Path $HOME 'mhw-mods'),
  (Join-Path $HOME 'source\repos\mhw-mods'),
  (Join-Path $HOME 'Documents\GitHub\mhw-mods'),
  (Join-Path $HOME 'Desktop\mhw-mods'),
  'C:\HeavenServices\mhw-mods'
)
$found=@()
foreach($p in $candidates){if(Test-Path -LiteralPath (Join-Path $p '.git')){$found+=$p}}
if(-not $found){
  $found=Get-ChildItem -LiteralPath $HOME -Directory -Recurse -Depth 4 -ErrorAction SilentlyContinue |
    Where-Object {$_.Name -eq 'mhw-mods' -and (Test-Path -LiteralPath (Join-Path $_.FullName '.git'))} |
    Select-Object -ExpandProperty FullName
}
$found | Sort-Object -Unique | ForEach-Object { $_ }
